what:
stdx::ensure_sufficient_stack is wrong on a fiber (crates/stdx/src/lib.rs:34). stacker keeps the stack limit per THREAD (stacker-0.1.25 src/lib.rs:120 STACK_LIMIT, from the thread's own stack). A job on a fiber of blaze_graph::sched::fiber runs on its own mmap'd stack, so remaining_stack() is sp minus the worker thread's limit: either saturates to 0 (a new 1/8 MiB segment mmap'd on EVERY call) or is huge (never grows: the fiber overflows into its guard page and the process dies). Asked by lane sched (phase 2, fibers; Andrew 18:29). Please add to crates/stdx/src/lib.rs:

thread_local! { static FIBER_STACK_LIMIT: Cell<usize> = const { Cell::new(0) }; }
/// The lowest usable address of the fiber stack this thread runs now; 0 on the thread's own stack.
#[inline(never)] pub fn fiber_stack_limit() -> usize { FIBER_STACK_LIMIT.get() }
#[inline(never)] pub fn set_fiber_stack_limit(limit: usize) { FIBER_STACK_LIMIT.set(limit) }

and in ensure_sufficient_stack (non-wasm): let limit = fiber_stack_limit(); if limit == 0 { stacker::maybe_grow(RED_ZONE, SEGMENT, f) } else { let here = { let x = 0u8; std::ptr::addr_of!(x).addr() }; if here.saturating_sub(limit) >= RED_ZONE { f() } else { stacker::grow(SEGMENT, || { let here = { let x = 0u8; std::ptr::addr_of!(x).addr() }; let segment = here - stacker::remaining_stack().expect("stacker knows a segment it made"); let outer = fiber_stack_limit(); set_fiber_stack_limit(segment); let out = f(); set_fiber_stack_limit(outer); out }) } }. (#[inline(never)] on the two accessors matters: a job can resume on another thread after a wait, and an inlined thread-local address could be kept across it.) Once it is in, sched registers it as a fiber::Carried (take = replace with 0, put = set) and sets each fiber's own limit at job start; tell lane sched.
